-- إضافة سجلات المدير والوكيل التفصيلية إلى قاموس التفويض
begin;

alter table public.platform_record_types add column if not exists route_url text, add column if not exists is_assignable boolean not null default true, add column if not exists supports_files boolean not null default true, add column if not exists supports_approval boolean not null default false, add column if not exists supports_analysis boolean not null default true, add column if not exists configuration_json jsonb not null default '{}'::jsonb, add column if not exists is_active boolean not null default true;

on conflict(module_key) do update set display_name=excluded.display_name,owner_role=excluded.owner_role,route_url=excluded.route_url,is_active=true;

on conflict(module_key,record_type) do update set display_name=excluded.display_name,route_url=excluded.route_url,is_assignable=excluded.is_assignable,supports_files=excluded.supports_files,supports_approval=excluded.supports_approval,supports_analysis=excluded.supports_analysis,configuration_json=excluded.configuration_json,is_active=true;

commit;

select module_key,record_type,display_name,route_url from public.platform_record_types where module_key in ('manager_records','deputy_academic','deputy_school_affairs','deputy_student_affairs','deputy_shared') order by module_key,display_name;